  1001→export function useDesktopRoutingHeaderSync(
  1002→  routing: Pick<DesktopRoutingApi, "setHeaderCenter" | "setHeaderRight" | "clearHeaderSlots">,
  1003→  centerContent: ReactNode | null | undefined,
  1004→  rightContent: ReactNode | null | undefined
  1005→) {
  1006→  const { setHeaderCenter, setHeaderRight, clearHeaderSlots } = routing;
  1007→
  1008→  useEffect(() => {
  1009→    setHeaderCenter(centerContent ?? null);
  1010→  }, [centerContent, setHeaderCenter]);
  1011→
  1012→  useEffect(() => {
  1013→    setHeaderRight(rightContent ?? null);
  1014→  }, [rightContent, setHeaderRight]);
  1015→
  1016→  useEffect(() => clearHeaderSlots, [clearHeaderSlots]);
  1017→}
